import { test, expect } from '@playwright/test';

test.describe('Search Filter Results Count', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display correct number of results for each filter option', async ({ page }) => {
    // Apply first filter option
    const filterByCategory = page.getByRole('button', { name: /filter by category/i });
    await filterByCategory.click();

    const categorySelect = page.getByRole('combobox', { name: /category/i });
    await categorySelect.setInputValue('books');

    const applyButton = page.getByRole('button', { name: /apply/i });
    await applyButton.click();

    // Verify results count is displayed
    const resultsCount = page.getByText(/10 results/i);
    await expect(resultsCount).toBeVisible();

    // Apply second filter option
    const filterByAuthor = page.getByRole('button', { name: /filter by author/i });
    await filterByAuthor.click();

    const authorSelect = page.getByRole('combobox', { name: /author/i });
    await authorSelect.setInputValue('J.K. Rowling');

    await applyButton.click();

    // Verify updated results count
    const updatedResultsCount = page.getByText(/5 results/i);
    await expect(updatedResultsCount).toBeVisible();

    // Apply third filter option
    const filterByPrice = page.getByRole('button', { name: /filter by price/i });
    await filterByPrice.click();

    const priceSelect = page.getByRole('combobox', { name: /price/i });
    await priceSelect.setInputValue('under $10');

    await applyButton.click();

    // Verify final results count
    const finalResultsCount = page.getByText(/2 results/i);
    await expect(finalResultsCount).toBeVisible();
  });

  test('should handle no results scenario', async ({ page }) => {
    // Apply first filter option
    const filterByCategory = page.getByRole('button', { name: /filter by category/i });
    await filterByCategory.click();

    const categorySelect = page.getByRole('combobox', { name: /category/i });
    await categorySelect.setInputValue('nonexistent category');

    const applyButton = page.getByRole('button', { name: /apply/i });
    await applyButton.click();

    // Verify no results message is displayed
    const noResultsMessage = page.getByText(/no results found/i);
    await expect(noResultsMessage).toBeVisible();

    // Verify results count is not displayed
    const resultsCount = page.getByText(/10 results/i);
    await expect(resultsCount).not.toBeVisible();

    // Verify results list is empty
    const resultsList = page.locator('[data-testid="results-list"]');
    await expect(resultsList).toHaveCount(0);
  });
});
